(()=>{const header=document.getElementById('siteHeader'),toggle=document.getElementById('menuToggle');if(new URLSearchParams(location.search).get('embed')==='1')document.body.classList.add('embed');if(!header||!toggle)return;const close=()=>{header.classList.remove('menu-open');toggle.setAttribute('aria-expanded','false')};toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';header.classList.toggle('menu-open',open);toggle.setAttribute('aria-expanded',String(open))});document.addEventListener('keydown',e=>{if(e.key==='Escape'){close();toggle.focus()}});document.addEventListener('click',e=>{if(!header.contains(e.target))close()});header.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',close));if(new URLSearchParams(location.search).get('question')&&!document.body.classList.contains('embed')){const q=new URLSearchParams(location.search).get('question');if(/^Q\d{3}$/.test(q)){const back=document.createElement('a');back.className='question-return';back.href='practice.html?q='+q;back.textContent='← Return to question '+q;back.style.cssText='display:block;max-width:1590px;margin:12px auto 0;padding:0 32px;font-size:12px';header.insertAdjacentElement('afterend',back)}}})();
if(new URLSearchParams(location.search).get('embed')==='1'){const stage=document.querySelector('.stage');if(stage){const bar=document.createElement('div');bar.className='embed-reference-controls';const b=document.createElement('button');b.textContent='Show surrounding anatomy';b.onclick=()=>{const bodyButton=document.getElementById('isolatePart');if(bodyButton){if(bodyButton.getAttribute('aria-pressed')==='true')bodyButton.click()}else document.getElementById('showall')?.click()};bar.append(b,document.createTextNode('Drag to rotate · Scroll to zoom'));stage.prepend(bar)}}
